'use strict';
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',studies:'M8 4H4v17h16V4h-5M9 3h6v4H9zM8 12h8M8 16h5',people:'M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M17 15a5 5 0 0 1 4 5M12 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',pulse:'M2 12h5l3-8 4 16 3-8h5',calendar:'M3 5h18v16H3zM7 3v4M17 3v4M3 10h18M8 14h1M15 14h1M8 18h1',query:'M21 11a9 9 0 0 1-9 9H5l-3 2 1-6a9 9 0 1 1 18-5ZM8 9h8M8 13h5',export:'M12 3v12m-4-4 4 4 4-4M4 15v5h16v-5',audit:'M4 5h16M4 12h16M4 19h16M8 3v4M16 10v4M8 17v4',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-1 5 6 6',bell:'M6 9a6 6 0 0 1 12 0c0 7 3 7 3 8H3c0-1 3-1 3-8M10 21h4',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',leaf:'M5 21C5 6 11 2 21 3c1 10-4 16-14 15M5 21 16 9M11 14h7M11 14V8',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',warn:'m12 3 10 18H2zM12 9v5M12 17h.01',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7h.01',logout:'M9 3H4v18h5M9 12h12m-4-4 4 4-4 4',menu:'M3 6h18M3 12h18M3 18h18',code:'m8 5-7 7 7 7m8-14 7 7-7 7M14 3l-4 18',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3M12 14v3'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Pending';
const timeLabel=v=>v?new Date(v).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Not recorded';
const pill=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
const button=(s,a,c='',i='',extra='')=>`<button type="button" class="button ${c}" data-action="${a}" ${extra}>${i?icon(i):''}${esc(s)}</button>`;
let config={demo_login:true},loginMode='demo';
let me,data,roles,page='overview',search='',studyFilter='',statusFilter='',toastTimer,refreshTask=null;
const nav=[['overview','grid','Overview'],['studies','studies','Studies'],['participants','people','Participants'],['visits','calendar','Visit schedule'],['safety','pulse','Safety & vigilance'],['queries','query','Data quality'],['compliance','shield','Ethics & regulatory'],['exports','export','Data exchange'],['audit','audit','Audit trail']];
const can=p=>me.permissions.includes(p);
const studyName=id=>data.studies.find(s=>s.id===id)?.title||id;
const match=r=>(!studyFilter||r.study_id===studyFilter||r.id===studyFilter)&&(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
const empty=(s='No records match your filters.')=>`<div class="empty">${icon('search')}<p>${esc(s)}</p></div>`;
async function api(path,body){const requestSession=me;const res=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''},body:JSON.stringify(body)});const r=await res.json();if(!res.ok){if(res.status===401&&path!='/api/login'&&me===requestSession){me=null;renderLogin();}throw new Error(r.error||'Request failed.');}return r;}
function toast(s,error=false){const t=document.querySelector('#toast');t.textContent=s;t.className=error?'show error':'show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',4500);}
function brand(){return '<div class="brand"><img src="/favicon.svg" alt=""><div><div class="brand-name">anvaya<span style="color:#8da47e">.</span></div><div class="brand-sub">Research workspace</div></div></div>';}
async function boot(){[roles,config]=await Promise.all([api('/api/roles'),api('/api/config')]);if(!config.demo_login)loginMode='named';try{me=await api('/api/me');if(me.must_change_password){renderPasswordChange();return;}data=await api('/api/data');renderShell();}catch{renderLogin();}}
function renderLogin(){document.querySelector('#app').innerHTML=`<div class="login-page"><section class="login-story">${brand()}<div><div class="eyebrow" style="color:#9fb69c;margin-bottom:25px">RESEARCH WITH CONTINUITY</div><h1>Every study.<br>Every milestone.<br><em>One clear view.</em></h1><p>A considered workspace for Ayurveda clinical research. Connect your studies, participant safety and research integrity.</p></div><div class="story-bottom"><span>SIH 2026 · PS 26046</span><span>Ayurveda clinical research</span></div></section><main class="login-panel" id="workspace"><form class="login-form" id="login-form"><div class="eyebrow">WELCOME TO ANVAYA</div><h2>Your research workspace</h2>${loginFields()}<div class="form-error" role="alert"></div><button class="button primary" type="submit">Open workspace ${icon('arrow')}</button><p class="login-disclaimer">SYNTHETIC DATA ONLY · Studies, people and registry references are fictional. Named accounts retain individual attribution. Shared demo roles remain available only when enabled.</p></form></main></div>`;}
function renderShell(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">RESEARCH WORKSPACE</div><nav aria-label="Main navigation">${nav.filter(([id])=>id!=='access'||can('users')).map(([id,i,s])=>`<button class="nav-button ${page===id?'active':''}" data-page="${id}" aria-label="${esc(s)}">${icon(i)}<span>${s}</span>${id==='safety'&&data.kpis.serious_pending?`<span class="count">${data.kpis.serious_pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-box"><strong>Built for Ayurveda research</strong><p>Synthetic portfolio<br>SIH 2026 · Problem 26046</p></div><button class="nav-button" data-page="about">${icon('info')} About this prototype</button><div class="sidebar-footer">anvaya · research in continuity</div></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Research workspace ${icon('chevron')} <strong id="breadcrumb">Overview</strong></div><div class="top-actions"><label class="search-box">${icon('search')}<input id="search" aria-label="Search current workspace" placeholder="Search workspace…" value="${esc(search)}"></label><div class="live"><span class="dot"></span> Live · 10s refresh</div><button class="icon-button" data-action="alerts" aria-label="View alerts">${icon('bell')}</button>${me.user_id?button('Account','account-password','small','lock'):''}<div class="profile"><div class="avatar">${esc(me.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><span>${esc(me.name)}<small>${esc(me.label)}</small></span></div><button class="icon-button" data-action="logout" aria-label="Switch demonstration role" title="Switch demonstration role">${icon('logout')}</button></div></header><div id="connection"></div><div class="workspace" id="workspace" tabindex="-1"></div></main></div>`;renderPage();}
function heading(t,s,a=''){return `<div class="page-heading"><div><div class="eyebrow">AIIA RESEARCH · SYNTHETIC DEMO</div><h1>${t}</h1><p>${s}</p></div><div class="button-row">${a}</div></div>`;}
function filters(statuses=[]){return `<div class="toolbar"><div class="filters"><select id="study-filter" aria-label="Filter by study"><option value="">All assigned studies</option>${data.studies.map(s=>`<option value="${esc(s.id)}" ${studyFilter===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select>${statuses.length?`<select id="status-filter" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select>`:''}</div><span class="muted" style="font-size:10px">${esc(me.label)} view</span></div>`;}
function stat(l,n,s,f,i,c=''){return `<article class="stat ${c}"><div class="stat-label">${l}${icon(i)}</div><div class="stat-number">${n}<small>${s}</small></div><div class="stat-foot">${f}</div></article>`;}
function chart(){const values=data.trend,max=Math.max(10,Math.ceil(data.kpis.enrolled/25)*25),W=520,H=175;const points=values.map((v,i)=>[42+i*(W-57)/7,12+(max-v.actual)/max*(H-36)]);const d=points.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ');return `<svg class="chart" viewBox="0 0 ${W} ${H+20}" role="img" aria-label="Cumulative enrolment from synthetic participant records"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c5d8b2" stop-opacity=".5"/><stop offset="100%" stop-color="#edf2e5" stop-opacity=".1"/></linearGradient></defs>${[0,1,2,3,4].map(i=>{let y=12+i*(H-36)/4;return `<line x1="42" x2="505" y1="${y}" y2="${y}" stroke="#edf1e8" stroke-dasharray="3 4"/><text x="30" y="${y+3}" text-anchor="end">${Math.round(max-i*max/4)}</text>`}).join('')}<path d="${d} L505,${H-24} L42,${H-24}Z" fill="url(#area)"/><path d="${d}" fill="none" stroke="#528160" stroke-width="2.5" stroke-linejoin="round"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3.4" fill="white" stroke="#528160" stroke-width="1.8"/><text x="${x}" y="${H+8}" text-anchor="middle">${new Date(values[i].date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</text>`).join('')}</svg>`;}
function alertList(all=false){return data.alerts.length?data.alerts.slice(0,all?100:3).map(a=>`<button class="alert ${a.level}" data-page="${a.page}">${icon(a.level==='danger'?'clock':'warn')}<div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p></div></button>`).join(''):empty('No alerts at current thresholds.');}
function studyTable(records){if(!records.length)return empty();return `<div class="table-wrap"><table><thead><tr><th>Study / protocol</th><th>Status</th><th>Enrolment</th><th>Study site</th><th>Oversight</th><th></th></tr></thead><tbody>${records.map(s=>`<tr><td><div class="study-cell"><div class="study-icon">${icon(s.type==='Observational'?'people':'leaf')}</div><div><button class="link-button" data-action="study-detail" data-id="${esc(s.id)}"><strong>${esc(s.title)}</strong></button><small>${esc(s.id)} · ${esc(s.type)}</small></div></div></td><td>${pill(s.status,s.status==='Setup'?'warning':s.status==='Follow-up'?'blue':'')}</td><td><div class="progress-label"><span>${s.enrolled} <span class="muted">/ ${s.target}</span></span><span>${s.progress}%</span></div><div class="progress"><span style="width:${Math.min(100,s.progress)}%"></span></div></td><td class="muted">${esc(s.site)}</td><td>${pill(s.risk,s.risk==='Attention'?'warning':'neutral')}</td><td><button class="link-button" data-action="study-detail" data-id="${esc(s.id)}" aria-label="Open ${esc(s.title)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function overview(){const k=data.kpis;return heading('Research overview','A clear view of your studies, people and priorities.',button('Export data','navigate-exports','','export'))+`<section class="welcome"><div><div class="eyebrow" style="margin-bottom:10px;color:#879575">YOUR PORTFOLIO, CONNECTED</div><h2>Good research starts with a clear picture.</h2><p>You have ${k.active_studies} recruiting studies and ${data.alerts.length} items that need attention. Here’s where things stand.</p></div><div class="welcome-art">${icon('leaf')}</div></section><div class="stats">${stat('Studies in portfolio',k.studies,'studies',`<span>${k.active_studies} recruiting</span> across assigned sites`,'studies')}${stat('Participants enrolled',k.enrolled,`/ ${k.target}`,`<span>${(k.target?Math.round(k.enrolled/k.target*100):0)}% of target</span> · cumulative enrolment`,'people')}${stat('Visit completion',k.visit_compliance===null?'—':k.visit_compliance+'%','',`${k.visits_complete} of ${k.visits_due} due visits completed`,'calendar')}${stat('Safety reports pending',k.serious_pending,'SAEs','Initial reporting requires attention','shield',k.serious_pending?'stat-alert':'')}</div><div class="grid-main"><section class="card"><div class="card-header"><div><h2>Recruitment progress</h2><p>Cumulative enrolment · last eight weekly snapshots</p></div><span class="chip">${icon('calendar')} 8 weeks</span></div><div class="card-body"><div class="chart-legend" style="margin-bottom:18px"><span><i></i>Participants enrolled</span><span>Synthetic records</span></div>${chart()}<div class="chart-summary"><span>Calculated from participant enrolment dates</span><strong>${k.enrolled} participants enrolled</strong></div></div></section><section class="card"><div class="card-header"><h2>Needs attention</h2><span class="alert-count">${data.alerts.length} alerts</span></div><div class="alerts">${alertList()}<button class="link-button" data-action="alerts" style="margin:4px 3px">View all priorities &nbsp; ↗</button></div></section></div><section class="card"><div class="card-header"><div><h2>Your studies</h2><p>Progress and oversight at a glance</p></div><button class="link-button" data-page="studies">View all studies &nbsp; ↗</button></div>${studyTable(data.studies.filter(match).slice(0,5))}<div class="table-footer"><span>${Math.min(5,data.studies.filter(match).length)} of ${data.studies.length} studies · synthetic portfolio</span><span>Updated ${timeLabel(data.server_time)}</span></div></section>`;}
function studiesPage(){const setup=data.studies.filter(s=>s.status==='Setup'),ready=setup.filter(s=>s.readiness.ready);return heading('Study portfolio','Review readiness, open recruitment and track study progress.',can('study')?button('New study','new-study','primary','plus'):'')+`<section class="study-summary"><div><span class="eyebrow">STUDY READINESS</span><h2>${setup.length} in setup · ${ready.length} ready to activate</h2><p>Record protocol, registration and ethics evidence before opening recruitment.</p></div>${setup.length?button('Review setup','study-detail','soft','shield',`data-id="${esc((ready[0]||setup[0]).id)}"`):pill('No studies awaiting setup','neutral')}</section>`+filters(['Recruiting','Setup','Follow-up','Completed'])+`<section class="card">${studyTable(data.studies.filter(s=>match(s)&&(!statusFilter||s.status===statusFilter)))}</section>`;}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;}
function restricted(s){return heading('Role-scoped access',esc(me.label))+`<section class="card"><div class="empty">${icon('lock')}<p>${esc(s)}</p><p style="margin-top:10px">Use the top-right switch-role button to explore another role.</p></div></section>`;}
function participantsPage(){if(me.role==='leadership')return restricted('Leadership receives aggregate metrics. Participant records belong to operational and oversight roles.');const records=data.participants.filter(p=>match(p)&&(!statusFilter||p.status===statusFilter));return heading('Participants & consent','Pseudonymous records. Consent stays visible at every step.',can('enrol')?button('Enrol participant','enrol','primary','plus'):'')+filters(['Enrolled','Withdrawn'])+`<div class="status-note">${icon('lock')} Synthetic records only. No names, phone numbers, Aadhaar numbers or ABHA identifiers are collected.</div><section class="card">${records.length?table(['Participant','Study','Prakriti','Consent','Enrolled',''],records.map(p=>`<tr><td><strong>${esc(p.id)}</strong><small class="muted" style="display:block;margin-top:5px">${p.age} years · ${esc(p.sex)} · ${esc(p.site)}</small></td><td><button class="link-button" data-action="study-detail" data-id="${esc(p.study_id)}">${esc(studyName(p.study_id))}</button></td><td>${esc(p.prakriti)}</td><td>${pill(p.consent?(p.reconsent_required?'Reconsent due · v':'Active · v')+p.consent_version:'Withdrawn',p.consent&&!p.reconsent_required?'':'warning')}<small class="muted" style="display:block;margin-top:5px">${esc(p.consent_language)}</small></td><td>${date(p.enrolled_at)}</td><td>${p.consent&&p.reconsent_required&&can('enrol')?button('Record reconsent','reconsent','small','',`data-id="${esc(p.id)}"`):''}${button('History','consent-history','small','',`data-id="${esc(p.id)}"`)}${p.consent&&can('withdraw')?button('Withdraw consent','withdraw','small','',`data-id="${esc(p.id)}"`):pill(p.status,'neutral')}</td></tr>`).join('')):empty()}</section>`;}
function visitsPage(){if(['leadership','ethics'].includes(me.role))return restricted('This role does not receive participant visit records.');const today=data.server_time.slice(0,10),records=data.visits.map(v=>({...v,status:v.cancelled?'Cancelled':v.completed_at?'Completed':v.due<today?'Overdue':v.due===today?'Due today':'Upcoming'})).filter(v=>match(v)&&(!statusFilter||v.status===statusFilter)).sort((a,b)=>a.due.localeCompare(b.due));return heading('Visit schedule','Keep follow-up on time and preserve protocol continuity.')+filters(['Overdue','Due today','Upcoming','Completed','Cancelled'])+`<section class="card">${records.length?table(['Visit','Participant','Study','Scheduled date','Status',''],records.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.participant_id)}</td><td>${esc(studyName(v.study_id))}</td><td>${date(v.due)}</td><td>${pill(v.status,v.status==='Overdue'?'danger':v.status==='Upcoming'?'neutral':'')}</td><td>${!v.completed_at&&v.consent_active&&!v.cancelled&&v.due<=today&&can('visit')?button('Record visit','complete-visit','small','',`data-id="${esc(v.id)}"`):`<span class="muted">${v.cancelled?'Consent withdrawn':v.completed_at?timeLabel(v.completed_at):!v.consent_active?'Consent action required':'Scheduled'}</span>`}</td></tr>`).join('')):empty()}</section>`;}
function countdown(due,done){if(done)return `<span style="color:#6e935b">Recorded ${timeLabel(done)}</span>`;if(!due)return '<span class="muted">Per protocol</span>';const h=(new Date(due)-new Date(data.server_time))/3600000;return `<span class="countdown ${h<0?'overdue':''}">${h<0?Math.abs(h).toFixed(1)+'h overdue':h<48?h.toFixed(1)+'h remaining':Math.ceil(h/24)+' days remaining'}</span>`;}
function safetyPage(){if(me.role==='leadership')return heading('Safety overview','Aggregate oversight for institutional leadership.')+`<div class="stats">${stat('Safety reports',data.safety_counts.total,'','Synthetic report count','pulse')}${stat('Serious reports',data.safety_counts.serious,'','Seriousness differs from severity','shield')}${stat('Initial reports pending',data.safety_counts.initial_pending,'','Action belongs to investigator / PV','clock','stat-alert')}</div><div class="status-note">Individual case narratives are excluded from the leadership API response. No causality or safety-signal inference is made.</div>`;const records=data.events.filter(e=>match(e)&&(!statusFilter||(statusFilter==='Serious'&&e.serious)||(statusFilter==='Non-serious'&&!e.serious)||(statusFilter==='Pending initial'&&!e.reported_at)));return heading('Safety & pharmacovigilance','Capture reports. Track deadlines. Keep decisions attributable.',can('safety')?button('Report adverse event','new-event','primary','plus'):'')+`<div class="status-note warning">NDCT timers appear only for studies flagged as applicable. Other serious reports use the internal SOP target. Recording a report does not send it to a regulator.</div>`+filters(['Serious','Non-serious','Pending initial'])+`<section class="card"><div class="card-header"><h2>Safety case inbox</h2><span class="chip">Human review required</span></div>${records.length?table(['Report / participant','Event','Classification','Initial report','Analysis report',''],records.map(e=>`<tr><td><button class="link-button" data-action="event-detail" data-id="${esc(e.id)}"><strong>${esc(e.id)}</strong></button><small class="muted" style="display:block;margin-top:6px">${esc(e.participant_id)}</small></td><td class="event-term">${esc(e.term)}<small class="muted" style="display:block;margin-top:5px">${esc(e.study_id)}</small></td><td>${pill(e.serious?'Serious':'Non-serious',e.serious?'danger':'neutral')}<small class="muted" style="display:block;margin-top:6px">${esc(e.severity)} severity</small></td><td>${countdown(e.initial_due,e.reported_at)}<small class="muted" style="display:block;max-width:190px;white-space:normal;font-size:9px;margin-top:5px">${esc(e.rule)}</small></td><td>${countdown(e.analysis_due,e.analysis_at)}</td><td>${can('report')&&(!e.reported_at||(e.analysis_due&&!e.analysis_at))?button(e.reported_at?'Record analysis':'Record initial','record-report','small','',`data-id="${esc(e.id)}" data-phase="${e.reported_at?'analysis':'initial'}"`):button('Details','event-detail','small','',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')):empty()}</section>`;}
function queriesPage(){if(['leadership','ethics'].includes(me.role))return restricted('Detailed data queries belong to study operations and monitoring roles.');const records=data.queries.filter(q=>match(q)&&(!statusFilter||q.status===statusFilter));return heading('Data quality','Resolve gaps between data capture and trusted evidence.')+filters(['Open','Resolved'])+`<section class="card"><div class="card-header"><h2>Data query register</h2><span class="chip">${data.kpis.open_queries} open queries</span></div>${records.length?table(['Query / study','Data field','Review request','Age','Status',''],records.map(q=>{const days=Math.floor((new Date(data.server_time)-new Date(q.opened_at))/86400000);return `<tr><td><strong>${esc(q.id)}</strong><small class="muted" style="display:block;margin-top:5px">${esc(q.study_id)}</small></td><td>${esc(q.field)}</td><td class="event-term">${esc(q.status==='Resolved'?q.resolution:q.message)}</td><td>${days} days ${days>=data.settings.query_days&&q.status==='Open'?pill('Aging','warning'):''}</td><td>${pill(q.status,q.status==='Open'?'warning':'')}</td><td>${q.status==='Open'&&can('query')?button('Resolve','resolve-query','small','',`data-id="${esc(q.id)}"`):''}</td></tr>`}).join('')):empty()}</section>`;}
function compliancePage(){
    const records=data.studies.filter(match);
    return heading('Ethics & regulatory','Review the evidence that opens recruitment.',can('settings')?button('Alert thresholds','settings','','settings'):'')+`<div class="status-note">Readiness checks use recorded study evidence. Registry references are fictional; this workspace does not verify external approval.</div>`+filters()+`<section class="card"><div class="card-header"><h2>Regulatory milestone register</h2><span class="chip">Protocol and consent versions tracked separately</span></div>${records.length?table(['Study','CTRI reference','IEC approval','Protocol / consent','Readiness',''],records.map(s=>{const approved=s.readiness.checks.find(c=>c.key==='ethics').passed;return `<tr><td><button class="link-button" data-action="study-detail" data-id="${esc(s.id)}">${esc(s.title)}</button><small class="muted" style="display:block;margin-top:6px">${esc(s.id)} · ${esc(s.status)}</small></td><td>${s.ctri?`<span style="font-size:10px">${esc(s.ctri)}</span><small class="muted" style="display:block;margin-top:6px">Registered ${date(s.registered_at)}</small>`:pill('Pending · enrolment locked','warning')}</td><td>${pill(approved?'Current':s.iec_days!==null&&s.iec_days<0?'Expired':'Evidence incomplete',approved?'':'warning')}<small class="muted" style="display:block;margin-top:6px">${s.iec_expiry?'Until '+date(s.iec_expiry):'Approval period missing'}</small></td><td>Protocol ${esc(s.protocol)}<small class="muted" style="display:block;margin-top:6px">Consent ${esc(s.consent_version)}</small></td><td>${pill(s.readiness.passed+' / '+s.readiness.total+' checks',s.readiness.ready?'':'warning')}</td><td>${button('Review','study-detail','small','',`data-id="${esc(s.id)}"`)}</td></tr>`}).join('')):empty()}</section><div class="grid-main section-gap"><section class="card"><div class="card-header"><h2>Readiness and activation</h2></div><div class="card-body"><p class="muted" style="line-height:1.8">Open a study to review each check. An administrator can save setup evidence, then activate recruitment. The enrolment API rechecks readiness for every participant.</p><div class="metric-row"><span>Studies in setup</span><strong>${data.studies.filter(s=>s.status==='Setup').length}</strong></div><div class="metric-row"><span>Ready for activation</span><strong>${data.studies.filter(s=>s.status==='Setup'&&s.readiness.ready).length}</strong></div><div class="metric-row"><span>Recruiting</span><strong>${data.kpis.active_studies}</strong></div></div></section><section class="card"><div class="card-header"><h2>Oversight reminders</h2></div><div class="alerts">${alertList(true)}</div></section></div>`;
}
function exportsPage(){return heading('Data exchange','Structured research data with explicit provenance and limits.',can('export')?button('Check FHIR links','check-exchange','','check'):'')+`<div class="status-note">Synthetic data exports: FHIR research JSON and DM / AE mapping-preview CSV. Full SDTM/ADaM/Define-XML and ABDM exchange require reviewed mappings and partner acceptance. Inspect the integration path below.</div><div class="cards-grid">${[['code','FHIR R4 bundle','Linked ResearchStudy, ResearchSubject, Patient and Consent resources.','FHIR R4 · JSON','fhir'],['people','Demographics mapping','Study, participant, site, age, sex and consent date mapped to a DM-shaped table.','SDTM DM preview · CSV','dm'],['pulse','Adverse event mapping','Verbatim events, severity, seriousness and occurrence time in an AE-shaped table.','SDTM AE preview · CSV','ae']].map(([i,t,d,l,k])=>`<section class="card export-card">${icon(i)}<span class="eyebrow">${l}</span><h3>${t}</h3><p>${d}</p>${can('export')?button('Download '+(k==='fhir'?'JSON':'CSV'),'download','primary','export',`data-kind="${k}"`):'<span class="read-only">Export permission required</span>'}</section>`).join('')}</div><div class="about-grid section-gap"><section class="card text-content"><h2>Two standards, different jobs</h2><p>FHIR supports structured exchange. CDISC supports research collection, tabulation, analysis and metadata. Conversion requires a reviewed semantic mapping.</p><div class="code-box">Source records<br>  ├─ FHIR R4 research bundle · working<br>  ├─ DM / AE mapping previews · working<br>  ├─ ABDM clinical DocumentBundle · partner validation required<br>  └─ Full CDISC package · mapping and expert review required</div></section><section class="card text-content"><h2>Integration readiness</h2>${button('View integration path','integration-page','small','arrow')}${[['Local record export','Working',''],['ABDM HIP / HIU connector','Partner access needed','neutral'],['Live CTRI submission','Not integrated','neutral'],['Licensed dictionary coding','Pending licence','warning'],['Production e-signatures','Validation needed','neutral']].map(([k,v,c])=>`<div class="metric-row"><span>${k}</span>${pill(v,c)}</div>`).join('')}</section></div>`;}
async function auditPage(){if(!can('audit')){document.querySelector('#workspace').innerHTML=restricted('Audit records require an authorised oversight role.')+footer();return;}const requestSession=me.csrf;const a=await api('/api/audit');if(page!=='audit'||me?.csrf!==requestSession)return;const records=a.entries.filter(r=>(!studyFilter||r.study_id===studyFilter)&&(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase())));document.querySelector('#workspace').innerHTML=heading('Audit & data integrity','Traceable changes, exports and review decisions.',button('Verify chain','verify-audit','','shield'))+`<div class="status-note ${a.verification.valid?'':'warning'}">${icon('shield')} ${a.verification.valid?'Chain verified':'Verification failed'} · ${a.verification.entries} events checked · SHA-256 linkage. Production immutability requires independently retained checkpoints and protected storage.</div>`+filters()+`<section class="card"><div class="card-header"><h2>Event ledger</h2><span class="chip">Append-only application history</span></div>${records.length?table(['Sequence / time','Actor','Action','Record / reason','Hash'],records.map(r=>`<tr><td>#${r.seq}<small class="muted" style="display:block;margin-top:5px">${timeLabel(r.timestamp)}</small></td><td>${esc(r.actor)}</td><td style="font-size:10px">${esc(r.action.replaceAll('_',' '))}</td><td class="audit-details"><details><summary>${esc(r.entity)} · ${esc(r.reason||'View recorded change')}</summary><pre class="code-box">${esc(JSON.stringify({before:r.before,after:r.after},null,2))}</pre></details></td><td><span class="hash" title="${esc(r.hash)}">${r.hash.slice(0,12)}…</span></td></tr>`).join('')):empty()}</section>`+footer();}
function aboutPage(){return heading('Built for research continuity','Anvaya · SIH 2026 · Problem statement 26046')+`<div class="about-grid"><section class="card text-content"><h2>Working prototype</h2><ul><li>Persistent portfolio and derived KPIs.</li><li>Named accounts, managed study assignments and session revocation.</li><li>Versioned document review, amendments and reconsent.</li><li>Reviewed synthetic CSV imports with duplicate protection.</li><li>Study setup, six readiness checks and audited activation.</li><li>Separate protocol and consent versions before enrolment.</li><li>AE / SAE capture and reporting clocks.</li><li>Visits, queries and consent withdrawal.</li><li>FHIR JSON and DM / AE mapping exports.</li><li>Append-only audit history and hash verification.</li></ul></section><section class="card text-content"><h2>Institutional validation still needed</h2><ul><li>Institutional SSO/MFA and hosting security acceptance.</li><li>Approved SOPs and electronic signatures.</li><li>Licensed MedDRA and WHODrug coding.</li><li>EDC, HIS, CTRI and ABDM integrations.</li><li>Validated CDISC submission packages.</li><li>India-resident cloud operations and security review.</li></ul></section><section class="card text-content"><h2>Evidence behind the design</h2><p><a href="https://sih.gov.in/sih2026PS" target="_blank" rel="noreferrer">SIH problem statement</a><br><a href="https://ctri.nic.in/Clinicaltrials/faq.php" target="_blank" rel="noreferrer">CTRI prospective registration</a><br><a href="https://www.cdsco.gov.in/opencms/opencms/en/Acts-and-rules/New-Drugs/" target="_blank" rel="noreferrer">CDSCO NDCT rules</a><br><a href="https://nrces.in/ndhm/fhir/r4/" target="_blank" rel="noreferrer">NRCeS ABDM implementation guide</a></p><p>Detailed requirements, sources and limitations are in the project’s docs folder.</p></section><section class="card text-content"><h2>Demonstration data</h2><p>Study titles, personnel, participants, events and registry references are fictional. Figures describe synthetic records, not AIIA’s actual portfolio or outcomes.</p><p>Role: <strong>${esc(me.label)}</strong><br>Scope: <strong>${me.scope?esc(me.scope.join(', ')):'All demo studies'}</strong></p><p>No treatment recommendations, causality decisions or automatic submissions are generated.</p></section></div>`;}
function footer(){return `<footer class="footer"><span>ANVAYA · Ayurveda research, connected. &nbsp; All data synthetic.</span><span>${date(data.server_time)} &nbsp; · &nbsp; ${esc(me.label)}</span></footer>`;}
function renderPage(){document.querySelectorAll('[data-page].nav-button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelector('#breadcrumb').textContent=nav.find(n=>n[0]===page)?.[2]||'About';const renderers={overview,studies:studiesPage,participants:participantsPage,visits:visitsPage,safety:safetyPage,queries:queriesPage,compliance:compliancePage,exports:exportsPage,about:aboutPage,...workflowPages};if(page==='audit'){document.querySelector('#workspace').innerHTML=heading('Audit & data integrity','Loading recorded events…');auditPage().catch(e=>toast(e.message,true));}else document.querySelector('#workspace').innerHTML=(renderers[page]||overview)()+footer();}
function navigate(target){page=target;search='';studyFilter='';statusFilter='';document.querySelector('#search').value='';document.querySelector('.sidebar').classList.remove('open');document.querySelector('#modal').close();renderPage();window.scrollTo(0,0);}
function modal(title,subtitle,html){const d=document.querySelector('#modal');d.className='modal';d.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${html}`;if(!d.open)d.showModal();}
function formWrap(id,body,label='Save record',attributes=''){return `<form id="${id}" ${attributes}>${body}<div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">${label}</button></div></form>`;}
function field(label,name,type='text',value='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;}
function select(label,name,options){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>typeof o==='string'?`<option value="${esc(o)}">${esc(o)}</option>`:`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`;}
function textarea(label,name,placeholder='',max=1000){return `<label class="field"><span>${label}</span><textarea name="${name}" placeholder="${esc(placeholder)}" maxlength="${max}" required></textarea></label>`;}
function localNow(){const n=new Date();return new Date(n-n.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function showEnrol(){modal('Enrol a participant','Synthetic adults only. Server checks registration, IEC approval and consent.',formWrap('enrol-form',select('Study','study_id',data.studies.map(s=>[s.id,s.title+' · '+s.status]))+`<div class="form-grid">${field('Age (years)','age','number','35','min="18" max="100"')}${select('Sex','sex',[['F','Female'],['M','Male'],['U','Unknown']])}${select('Prakriti assessment','prakriti',['Vata-Pitta','Pitta-Kapha','Vata-Kapha','Balanced','Not assessed'])}${select('Consent language','consent_language',['English','Hindi','Marathi'])}${field('Approved consent version','consent_version','text',data.studies[0]?.consent_version||'','maxlength="30"')}</div><label class="checkbox"><input name="consent" type="checkbox" required><span>I confirm the synthetic participant’s consent is documented using the current approved version. This records metadata, not a validated electronic signature.</span></label>`,'Enrol participant'));}
function showEvent(){modal('Record an adverse event','Preserve the narrative. Seriousness and severity are separate assessments.',formWrap('event-form',select('Participant','participant_id',data.participants.map(p=>[p.id,p.id+' · '+studyName(p.study_id)]))+field('Verbatim event term','term','text','','maxlength="160"')+`<div class="form-grid">${select('Seriousness criterion','seriousness',['Non-serious','Hospitalisation','Life-threatening','Death','Disability','Congenital anomaly','Other medically important event'])}${select('Severity','severity',['Mild','Moderate','Severe'])}${field('Occurrence time (your local time)','occurred_at','datetime-local',localNow())}${field('First awareness (your local time)','awareness_at','datetime-local',localNow())}</div>`+textarea('Reported narrative','narrative','Synthetic narrative only. Do not enter personal information.',2000)+`<div class="status-note">Coding stays pending licensed dictionary review. No causality is inferred.</div>`,'Record event'));}
function details(items){return `<div class="detail-grid">${items.map(([l,v])=>`<div class="detail-item"><small>${esc(l)}</small><strong>${esc(v)}</strong></div>`).join('')}</div>`;}
function readinessPanel(s){const r=s.readiness;return `<section class="readiness" aria-label="Study readiness checks"><div class="readiness-heading"><div><span class="eyebrow">${s.status==='Setup'?'ACTIVATION CHECKLIST':'RECORDED READINESS'}</span><h3>${r.passed} of ${r.total} checks passed</h3></div>${pill(r.ready?'Ready': 'Action needed',r.ready?'':'warning')}</div><ul class="readiness-list">${r.checks.map(c=>`<li class="${c.passed?'passed':'blocked'}">${icon(c.passed?'check':'warn')}<div><strong>${esc(c.label)}</strong><p>${esc(c.detail)}</p>${c.passed?'':`<small>${esc(c.error)}</small>`}</div><span>${c.passed?'Passed':'Required'}</span></li>`).join('')}</ul><details class="clinical-rationale"><summary>Why these checks matter</summary><p>Prospective registration makes the study publicly identifiable before recruitment. Current IEC approval confirms the recorded review period. Current-version consent protects the participant’s informed choice. These gates reduce the risk of enrolment before these prerequisites are documented; they do not independently authenticate external approvals.</p><a href="https://ctri.nic.in/Clinicaltrials/faq.php" target="_blank" rel="noreferrer">CTRI guidance</a> · <a href="https://ethics.ncdirindia.org/icmr_ethical_guidelines.aspx" target="_blank" rel="noreferrer">ICMR ethics guidance</a></details></section>`;}
function studyDetail(id){
    const s=data.studies.find(s=>s.id===id);if(!s)return;
    const actions=can('study')&&s.status==='Setup'?`<div class="button-row section-gap">${button('Edit study setup','study-setup','','settings',`data-id="${esc(id)}"`)}${button('Activate recruitment','activate-study','primary','check',`data-id="${esc(id)}" ${s.readiness.ready?'':'disabled'}`)}</div>`:'';
    modal(s.title,s.id+' · Synthetic study · record revision '+s.revision,`<div class="button-row">${pill(s.status)}${pill(s.risk,s.risk==='Attention'?'warning':'neutral')}</div>${actions}${readinessPanel(s)}`+details([['Enrolment',s.enrolled+' / '+s.target],['Site',s.site],['Investigator',s.pi||'Not assigned'],['Design',s.type],['Formulation / regimen',s.formulation],['Batch',s.batch||'Not recorded'],['Protocol version',s.protocol],['Consent version',s.consent_version],['Registry reference',s.ctri||'Pending'],['IEC approval reference',s.iec_reference||'Pending'],['IEC approval date',s.iec_approved_at?date(s.iec_approved_at):'Not recorded'],['IEC approval until',date(s.iec_expiry)],['Safety pathway',s.ndct?'NDCT flagged · demo':'Protocol SOP · '+s.safety_hours+' hours'],['Activated',s.activated_at?timeLabel(s.activated_at)+' · '+s.activated_by:'No activation action recorded']])+`<div class="status-note">Checks use the evidence entered in this workspace. Registry and IEC records are fictional and are not verified against external systems.</div>`);
}
function showStudySetup(id){
    const s=data.studies.find(s=>s.id===id);if(!s)return;
    const optional=(label,name,type='text',value='',extra='')=>field(label,name,type,value,extra).replace(' required>','>');
    const body=`<div class="status-note">Save incomplete evidence as a draft. Activation stays locked until every readiness check passes.</div><fieldset class="form-section"><legend>Protocol and responsibility</legend><div class="form-grid">${field('Protocol version','protocol','text',s.protocol,'maxlength="30"')}${field('Current consent version','consent_version','text',s.consent_version,'maxlength="30"')}${optional('Responsible investigator','pi','text',s.pi==='Not assigned'?'':s.pi,'maxlength="120"')}${optional('Formulation batch reference','batch','text',s.batch==='Not assigned'?'':s.batch,'maxlength="120"')}${field('Study start','start','date',s.start)}${field('Study end','end','date',s.end)}</div>${field('Formulation / regimen / observational scope','formulation','text',s.formulation,'maxlength="200"')}</fieldset><fieldset class="form-section"><legend>Prospective registration</legend><p>Use a fictional DEMO-CTRI reference. A REF application number cannot open recruitment.</p><div class="form-grid">${optional('CTRI registration reference','ctri','text',s.ctri,'maxlength="120"')}${optional('Registration date','registered_at','date',s.registered_at)}</div></fieldset><fieldset class="form-section"><legend>Ethics approval evidence</legend><p>Record the approval period and reference for this protocol and consent version.</p>${optional('IEC approval reference','iec_reference','text',s.iec_reference==='Pending approval'?'':s.iec_reference,'maxlength="120"')}<div class="form-grid">${optional('IEC approval date','iec_approved_at','date',s.iec_approved_at||'')}${optional('IEC expiry date','iec_expiry','date',s.iec_expiry)}</div></fieldset>${textarea('Reason for setup update','reason','Identify the synthetic evidence reviewed and the reason for this update.',500)}`;
    modal('Edit study setup',s.title+' · Revision '+s.revision,formWrap('study-setup-form',body,'Save setup',`data-id="${esc(id)}" data-revision="${s.revision}"`));
}
function showActivation(id){const s=data.studies.find(s=>s.id===id);if(!s)return;modal('Activate recruitment',s.title+' · Server rechecks readiness before committing.',formWrap('activation-form',readinessPanel(s)+`<label class="checkbox"><input type="checkbox" name="reviewed" required><span>I reviewed the recorded protocol, consent, registry and ethics evidence for this synthetic study.</span></label>`+textarea('Activation decision and evidence','reason','Explain the activation decision for the audit record.',500),'Activate recruitment',`data-id="${esc(id)}" data-revision="${s.revision}"`));}
function eventDetail(id){const e=data.events.find(e=>e.id===id);if(!e)return;modal(e.id+' · Safety record',studyName(e.study_id),`<h3>${esc(e.term)}</h3><p class="muted" style="line-height:1.8;margin:12px 0">${esc(e.narrative)}</p>`+details([['Participant',e.participant_id],['Seriousness',e.seriousness],['Severity',e.severity],['Occurrence',timeLabel(e.occurred_at)],['Awareness',timeLabel(e.awareness_at)],['Server receipt',timeLabel(e.created_at)],['Initial deadline',e.initial_due?timeLabel(e.initial_due):'Per protocol'],['Analysis deadline',e.analysis_due?timeLabel(e.analysis_due):'Per protocol'],['Rule source',e.rule],['Coding',e.coding],['Initial reference',e.report_reference||'Not recorded'],['Analysis reference',e.analysis_reference||'Not recorded']])+safetyActions(e));}
async function refresh(force=false){
    if(refreshTask){if(!force)return;await refreshTask;}
    if(!me||me.must_change_password)return;
    const requestSession=me.csrf;
    const task=(async()=>{try{const next=await api('/api/data');if(me?.csrf!==requestSession)return;data=next;document.querySelector('#connection').innerHTML='';if(force||(!document.querySelector('#modal').open&&!document.querySelector('#workspace details[open]')&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)))renderPage();}catch(e){if(me?.csrf===requestSession&&document.querySelector('#connection'))document.querySelector('#connection').innerHTML='<div class="offline-bar">Connection interrupted. Showing the last fetched records; changes require the server.</div>';}})();
    refreshTask=task;await task;if(refreshTask===task)refreshTask=null;
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button,a[data-action]');if(!el)return;if(el.dataset.page){navigate(el.dataset.page);return;}const action=el.dataset.action,id=el.dataset.id;try{
if(await workflowAction(action,el))return;
if(action==='menu')document.querySelector('.sidebar').classList.toggle('open');
if(action==='close-modal')document.querySelector('#modal').close();
if(action==='logout'){await api('/api/logout',{});me=null;document.querySelector('#modal').close();renderLogin();}
if(action==='navigate-exports')navigate('exports');
if(action==='alerts')modal('Your research priorities',data.alerts.length+' items need attention',alertList(true));
if(action==='study-detail')studyDetail(id);
if(action==='study-setup')showStudySetup(id);
if(action==='activate-study')showActivation(id);
if(action==='event-detail')eventDetail(id);
if(action==='enrol')showEnrol();
if(action==='new-event')showEvent();
if(action==='new-study')modal('Create a study','New studies stay in setup, with enrolment locked pending review.',formWrap('study-form',field('Study title','title','text','','maxlength="120"')+`<div class="form-grid">${field('Research area','condition','text','','maxlength="100"')}${field('Target enrolment','target','number','40','min="1" max="10000"')}${select('Intervention design','type',['Observational','Compound formulation','Single-herb formulation','Procedure','Whole-system regimen'])}${select('Study site','site',['Delhi','Goa','Jaipur'])}</div>`+field('Formulation / regimen / observational scope','formulation','text','','maxlength="200"'),'Create draft study'));
if(action==='withdraw')modal('Record consent withdrawal',id+' · Existing records are retained for review.',formWrap('withdraw-form',textarea('Reason and context','reason','Document withdrawal. Future routine visits will be blocked.'),'Record withdrawal',`data-id="${esc(id)}"`));
if(action==='complete-visit')modal('Record a completed visit',id+' · Server records actual entry time.',formWrap('visit-form',textarea('Source verification / reason','reason','Confirm visit completion. Explain late entry if applicable.'),'Record visit',`data-id="${esc(id)}"`));
if(action==='resolve-query')modal('Resolve data query',id+' · Preserve a source verification explanation.',formWrap('query-form',textarea('Resolution and source verification','resolution'),'Resolve query',`data-id="${esc(id)}"`));
if(action==='record-report')modal('Record '+el.dataset.phase+' report',id+' · Tracks external reporting. This does not send a report.',formWrap('report-form',field('External receipt / submission reference','reference','text','','maxlength="160"')+textarea('Recipients, evidence and delay explanation','reason','Record recipients and evidence; explain any delay.',500),'Record reporting step',`data-id="${esc(id)}" data-phase="${el.dataset.phase}"`));
if(action==='settings')modal('Operational alert thresholds','Statutory SAE clocks cannot be changed here.',formWrap('settings-form',field('Recruitment alert below % of planned pace','enrolment_threshold','number',data.settings.enrolment_threshold,'min="1" max="100"')+field('IEC expiry warning (days)','iec_days','number',data.settings.iec_days,'min="1" max="180"')+field('Flag open queries after (days)','query_days','number',data.settings.query_days,'min="1" max="90"'),'Save thresholds'));
if(action==='verify-audit'){const a=await api('/api/audit');toast(a.verification.valid?`Verified ${a.verification.entries} events. Hash links intact.`:'Audit verification failed.',!a.verification.valid);}
if(action==='download'){el.disabled=true;try{const res=await fetch('/api/export/'+el.dataset.kind);if(!res.ok){const e=await res.json();throw new Error(e.error);}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=el.dataset.kind==='fhir'?'anvaya-synthetic-fhir-r4.json':el.dataset.kind.toUpperCase()+'-mapping-preview.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded and recorded in audit history.');}finally{el.disabled=false;}}
}catch(e){toast(e.message,true);}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){search=ev.target.value;renderPage();}});
document.addEventListener('change',ev=>{if(ev.target.matches('#enrol-form select[name=study_id]')){ev.target.form.elements.consent_version.value=data.studies.find(s=>s.id===ev.target.value)?.consent_version||'';}if(ev.target.id==='study-filter'){studyFilter=ev.target.value;renderPage();}if(ev.target.id==='status-filter'){statusFilter=ev.target.value;renderPage();}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,fields=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type="submit"]'),error=form.querySelector('.form-error');error.textContent='';submit.disabled=true;try{if(await workflowSubmit(form,fields))return;let path,body=fields,message='Record saved.';
if(form.id==='login-form'){await api('/api/login',fields);me=await api('/api/me');if(me.must_change_password){renderPasswordChange();return;}data=await api('/api/data');page='overview';search='';studyFilter='';statusFilter='';renderShell();return;}
if(form.id==='enrol-form'){path='/api/enrolments';body={...fields,age:Number(fields.age),consent:form.elements.consent.checked};message='Participant enrolled. Consent, visits and audit event recorded.';}
if(form.id==='event-form'){path='/api/safety';body={...fields,occurred_at:new Date(fields.occurred_at).toISOString(),awareness_at:new Date(fields.awareness_at).toISOString()};message='Safety event recorded. Review reporting deadlines.';}
if(form.id==='study-form'){path='/api/studies';body={...fields,target:Number(fields.target)};message='Draft study created. Enrolment remains locked.';}
if(form.id==='study-setup-form'){path='/api/studies/'+form.dataset.id+'/setup';body={...fields,revision:Number(form.dataset.revision)};message='Study setup saved. Review the readiness checks.';}
if(form.id==='activation-form'){path='/api/studies/'+form.dataset.id+'/activate';body={...fields,revision:Number(form.dataset.revision),reviewed:form.elements.reviewed.checked};message='Recruitment activated. Decision recorded in audit history.';}
if(form.id==='query-form'){path='/api/queries/'+form.dataset.id+'/resolve';message='Query resolved with an audit record.';}
if(form.id==='withdraw-form'){path='/api/participants/'+form.dataset.id+'/withdraw';message='Withdrawal recorded. Routine study visits are blocked.';}
if(form.id==='visit-form'){path='/api/visits/'+form.dataset.id+'/complete';message='Visit completion recorded.';}
if(form.id==='report-form'){path='/api/safety/'+form.dataset.id+'/report';body={...fields,phase:form.dataset.phase};message='External reporting step recorded. This app sent no report.';}
if(form.id==='settings-form'){path='/api/settings';body=Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,Number(v)]));message='Alert thresholds saved.';}
if(!path)throw new Error('Unknown form.');const result=await api(path,body);document.querySelector('#modal').close();await refresh(true);if(['study-form','study-setup-form','activation-form'].includes(form.id))studyDetail(result.record.id);toast(message);
}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}});
document.querySelector('#modal').addEventListener('click',ev=>{if(ev.target.id==='modal'){const b=ev.target.getBoundingClientRect();if(ev.clientX<b.left||ev.clientX>b.right||ev.clientY<b.top||ev.clientY>b.bottom)ev.target.close();}});
// ponytail: polling suits a small demo; use push events when multi-site traffic warrants them.
setInterval(()=>{if(!document.hidden)refresh();},10000);
boot().catch(e=>{document.querySelector('#app').innerHTML='<div class="loading">Cannot connect. Run <code>python3 server.py</code>, then reload.</div>';toast(e.message,true);});
